Lemma qput_A_spec_L : forall ra sp gp tp t0 t1 t2 s0 s1 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (c cache stack M n b1 lo : Z) (ctx : word) (shj : list byte),
  (0x66f000 <= M /\ M + 16 + ru8' n <= kLowMemEnd + 1)%Z -> (M mod 16 = 0)%Z -> (M + 16 + ru8' n <= kHighMemEnd + 1)%Z -> (M + 16 + ru8' n <= lo)%Z ->
  (1 <= n <= 2^28)%Z -> (0 <= b1 < 256)%Z ->
  rw_cells asegs m M [C1 (Z_to_bv 8 3); C1 (Z_to_bv 8 b1); C2 (Z_to_bv 64 0); C4 (Z_to_bv 64 n); C8 ctx] ->
  rw_cells asegs m (shad (M + 16)) [CB (Z.to_nat (ru8' n / 8)) shj] ->
  rw_cells asegs m q_max [C8 (Z_to_bv 64 0x10000000)] -> rw_cells asegs m q_cmax [C8 (Z_to_bv 64 0x100000)] ->
  rw_cells asegs m g_GOT_asan_flags [C8 (Z_to_bv 64 g_asan_flags)] -> rw_cells asegs m (g_asan_flags + 48) [C4 (Z_to_bv 64 0)] ->
  ps_cells m ->
  stk asegs m lo (bv_unsigned sp) -> (lo <= bv_unsigned sp - 144)%Z -> (kHighShadowEnd + 8 <= lo)%Z ->
  mem_inv asegs m ->
  evt asegs (qput_A_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc c cache stack M n lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 QUAR) (Z_to_bv 64 c) (Z_to_bv 64 cache) (Z_to_bv 64 stack) (Z_to_bv 64 M)
             (Z_to_bv 64 n) a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
